interface.definition:
{
  #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3858221"(interview: ri!interview),
  #"SYSTEM_SYSRULES_sectionLayout_v1"(
    label: "Interviewer Feedback",
    labelColor: "SECONDARY",
    contents: {
      #"SYSTEM_SYSRULES_richTextDisplayField"(
        labelPosition: "COLLAPSED",
        value: #"SYSTEM_SYSRULES_richTextItem_v1"(
          text: "Completed by Interviewer",
          style: "EMPHASIS"
        )
      ),
      #"SYSTEM_SYSRULES_cardLayout"(
        contents: {
          #"SYSTEM_SYSRULES_richTextDisplayField"(
            labelPosition: "COLLAPSED",
            value: {
              #"SYSTEM_SYSRULES_richTextHeader"(
                text: "Are you supportive of the candidate being extended an offer for a DPP rotation?",
                size: "SMALL"
              ),
              #"SYSTEM_SYSRULES_richTextIcon"(icon: "question-circle-o", color: "ACCENT"),
              "  ",
              #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                value: ri!interview.supportExtensionOfOffer,
                isBoolean: true
              )
            }
          ),
          #"SYSTEM_SYSRULES_richTextDisplayField"(
            labelPosition: "COLLAPSED",
            value: {
              #"SYSTEM_SYSRULES_richTextHeader"(
                text: "Interview Feedback",
                size: "SMALL"
              ),
              #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: ri!interview.interviewFeedback)
            }
          ),
          #"SYSTEM_SYSRULES_richTextDisplayField"(
            labelPosition: "COLLAPSED",
            value: {
              #"SYSTEM_SYSRULES_richTextHeader"(
