              #"SYSTEM_SYSRULES_richTextIcon"(icon: "question-circle-o", color: "ACCENT"),
              "  ",
              #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                value: ri!interview.recommendAnotherInterview,
                isBoolean: true
              )
            }
          ),
          #"SYSTEM_SYSRULES_richTextDisplayField"(
            labelPosition: "COLLAPSED",
            value: {
              #"SYSTEM_SYSRULES_richTextHeader"(
                text: "Provide Name(s)",
                size: "SMALL"
              ),
              #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: ri!interview.recommendAnotherInterviewDesc)
            }
